// TaskBundle 可移植的任务包（技术设计第 15.5 节），由 exportTask 生成，importTask 读取。它只描述任务本身：任务名、版本的清单和文件、
// 触发器定义。不含运行记录、凭证的值和绑定、webhook 令牌，也不含项目、用户、任务等任何 ID，导入到哪个项目由导入的人决定。
type TaskBundle struct {
	// ActiveVersion 导出时激活的版本号（源部署中的版本号），没有激活版本时为 null。只作参考，导入后的任务不激活。
	ActiveVersion *int `json:"active_version"`

	// Console 任务在控制台上的显示选项，导入时照搬。较早导出的任务包没有这个字段，按默认值处理。
	Console    *TaskConsole `json:"console,omitempty"`
	ExportedAt time.Time    `json:"exported_at"`

	// Format 固定为 `lerryn.task-bundle`。
	Format TaskBundleFormat `json:"format"`

	// FormatVersion 任务包格式的版本，目前为 1。
	FormatVersion int `json:"format_version"`

	// Name 任务名：1 到 63 个字符，只能包含小写字母、数字和连字符，以字母或数字开头。在项目内唯一。
	//
	// Examples: weekday-digest
	Name TaskName `json:"name"`

	// OmittedVersions 导出版本历史时，因数量或大小上限没有带上的更早版本数。只导出一个版本时为 0。
	OmittedVersions int `json:"omitted_versions"`

	// ServerVersion 导出时的服务端版本，只用于排查问题。
	ServerVersion string `json:"server_version"`

	// Triggers 触发器定义，与 setTriggers 的请求相同，不含 webhook 令牌。没有导出触发器时为 null。
	Triggers *[]TriggerInput `json:"triggers"`

	// Versions 版本，按版本号从旧到新排列。最后一个是导出时所选的版本。
	Versions []TaskBundleVersion `json:"versions"`
}

// TaskBundleFormat 固定为 `lerryn.task-bundle`。
