// TaskCredentialAs defines model for TaskCredential.As.
type TaskCredentialAs string

// TaskCredentialStatus bound 已绑定且有效；missing 没有绑定；revoked、expired 绑定的凭证已撤销或已过期。
type TaskCredentialStatus string

